$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\mission_orchestrator.py"
$testPath = Join-Path $pkg "tests\test_mission_orchestrator.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $backlogPath)) { throw "AHOS_BACKLOG.json not found." }
if (-not (Test-Path $python)) { throw "Python venv not found." }

[IO.File]::WriteAllBytes(
    $modulePath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-030" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-030"
        title = "Add department manager and multi-worker mission orchestrator"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Create a department-manager planning layer and a dependency-aware multi-worker mission orchestrator. A manager leases itself for planning, produces a validated step graph through an injected planner, routes each step to the correct virtual worker, hands completed-step summaries downstream, requires QA on every step, and stops the mission on failures or approval gates. No live AI or external actions in this task."
    }
    [IO.File]::WriteAllText(
        $backlogPath,
        ($b | ConvertTo-Json -Depth 12),
        (New-Object System.Text.UTF8Encoding($false))
    )
}

Write-Host "=== AHOS-030 DEPARTMENT MANAGER + MULTI-WORKER ORCHESTRATOR ==="
Write-Host "Manager -> plan -> Research/Worker(s) -> QA -> downstream handoff."
Write-Host "No OpenAI calls. No paid API calls. No external business actions."
Write-Host ""

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}
if ($testExit -ne 0) { throw "AHOS-030 tests failed." }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-030" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/mission_orchestrator.py ahos_core/tests/test_mission_orchestrator.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): add multi-worker mission orchestrator"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-030 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-030 -> completed"
Write-Host "Git push: PASS"
Write-Host "Department manager planning: ENABLED"
Write-Host "Dependency-aware multi-worker routing: ENABLED"
Write-Host "Cross-worker result handoff: ENABLED"
Write-Host "Per-step QA gate: ENABLED"
Write-Host "Failure/approval fail-closed behavior: ENABLED"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
